{"command":"cd /workspace; cat > src/strsim.rs <<'EOF'
//! String similarity used for "did you mean" suggestions.

fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }

    let search_range = (a_len.max(b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;

    for (i, ac) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b_len - 1).min(i + search_range);
        for j in 0..=max_bound {
            if min_bound <= j && *ac == b[j] && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }

    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let d = jaro(a, b);
    let prefix = a
        .chars()
        .zip(b.chars())
        .take_while(|(x, y)| x == y)
        .count();
    let r = d + (0.1 * prefix as f64 * (1.0 - d));
    if r <= 1.0 {
        r
    } else {
        1.0
    }
}

/// Returns candidates with a confidence above 0.8, sorted by ascending confidence.
pub fn did_you_mean(v: &str, candidates: &[&str]) -> Vec<String> {
    let mut found: Vec<(f64, String)> = candidates
        .iter()
        .map(|c| (jaro_winkler(v, c), c.to_string()))
        .filter(|(conf, _)| *conf > 0.8)
        .collect();
    found.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
    found.into_iter().map(|(_, s)| s).collect()
}
EOF"}

