/// Result of a successful parse.
pub struct Matches {
    pub sub: &'static str,
    pub vals: Vec<Option<String>>,
    pub l: bool,
}

impl Matches {
    pub fn get(&self, i: usize) -> Option<&str> {
        self.vals.get(i).and_then(|v| v.as_deref())
    }
}

struct Ctx {
    bin: Option<String>,
}

impl Ctx {
    /// name used for the top level command in usage strings
    fn top_name(&self) -> String {
        self.bin.clone().unwrap_or_else(|| "jt".to_string())
    }

    fn sub_bin(&self, sc: &SubSpec) -> String {
        match &self.bin {
            Some(b) => format!("{} {}", b, sc.name),
            None => sc.name.to_string(),
        }
    }

    fn top_usage(&self) -> String {
        format!("USAGE:\n    {} <SUBCOMMAND>", self.top_name())
    }

    fn sub_usage_no_title(&self, sc: &SubSpec) -> String {
        if let Some(u) = sc.override_usage {
            return u.to_string();
        }
        let mut s = self.sub_bin(sc);
        for p in sc.positionals {
            if p.required {
                s.push_str(&format!(" <{}>", p.name));
            } else {
                s.push_str(&format!(" [{}]", p.name));
            }
        }
        s
    }

    fn sub_usage(&self, sc: &SubSpec) -> String {
        format!("USAGE:\n    {}", self.sub_usage_no_title(sc))
    }

    /// usage built from the given "used" arguments
    fn sub_smart_usage(&self, sc: &SubSpec, help_used: bool, l_used: bool, present: &[bool]) -> String {
        if let Some(u) = sc.override_usage {
            return format!("USAGE:\n    {}", u);
        }
        let any_used = help_used || l_used || present.iter().any(|p| *p);
        if !any_used {
            return self.sub_usage(sc);
        }
        let mut s = self.sub_bin(sc);
        if help_used {
            s.push_str(" --help");
        }
        if l_used {
            s.push_str(" -l");
        }
        for (i, p) in sc.positionals.iter().enumerate() {
            if p.required || present[i] {
                s.push_str(&format!(" <{}>", p.name));
            }
        }
        format!("USAGE:\n    {}", s)
    }

    fn sub_help(&self, sc: &SubSpec) -> String {
        let bin = self.sub_bin(sc);
        let display = if bin.contains(' ') { bin.replace(' ', "-") } else { sc.name.to_string() };
        format!(
            "{} \n{}\n\nUSAGE:\n    {}\n\n{}",
            display,
            sc.about,
            self.sub_usage_no_title(sc),
            sc.sections
        )
    }
}

const TRY_HELP: &str = "\n\nFor more information try --help\n";

fn fail(msg: String) -> ! {
    let _ = std::io::stdout().flush();
    let mut err = std::io::stderr();
    let _ = err.write_all(msg.as_bytes());
    let _ = err.flush();
    std::process::exit(2);
}

fn show(msg: &str) -> ! {
    let mut out = std::io::stdout();
    let _ = out.write_all(msg.as_bytes());
    let _ = out.flush();
    std::process::exit(0);
}

fn unknown_argument(arg: &str, suggestion: Option<&str>, usage: &str) -> ! {
    let mut s = format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
    if let Some(sg) = suggestion {
        s.push_str(&format!("\n\n\tDid you mean '{}'?", sg));
    }
    if arg.starts_with('-') {
        s.push_str(&format!(
            "\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`",
            arg, arg
        ));
    }
    s.push_str("\n\n");
    s.push_str(usage);
    s.push_str(TRY_HELP);
    fail(s)
}

fn too_many_values(val: &str, arg: &str, usage_no_title: &str) -> ! {
    let s = format!(
        "error: The value '{}' was provided to '{}' but it wasn't expecting any more values\n\n{}{}",
        val, arg, usage_no_title, TRY_HELP
    );
    fail(s)
}

fn unrecognized_subcommand(sub: &str, usage: &str) -> ! {
    fail(format!("error: The subcommand '{}' wasn't recognized\n\n{}{}", sub, usage, TRY_HELP))
}

fn all_subcommand_names() -> Vec<&'static str> {
    let mut v = Vec::new();
    for sc in SUBS {
        v.push(sc.name);
        for a in sc.aliases {
            v.push(*a);
        }
    }
    v
}

fn find_sub(name: &str) -> Option<&'static SubSpec> {
    SUBS.iter().find(|sc| sc.name == name || sc.aliases.iter().any(|a| *a == name))
}

fn split_eq(s: &str) -> (&str, Option<&str>) {
    match s.find('=') {
        Some(i) => (&s[..i], Some(&s[i + 1..])),
        None => (s, None),
    }
}

pub fn parse(args: &[String], bin: Option<String>) -> Matches {
    let ctx = Ctx { bin };
    let mut trailing = false;
    for (i, a) in args.iter().enumerate() {
        if !trailing {
            if let Some(sc) = find_sub(a) {
                if sc.name == "help" {
                    help_subcommand(&ctx, &args[i + 1..]);
                }
                return parse_sub(&ctx, sc, &args[i + 1..]);
            }
            if a == "--" {
                trailing = true;
                continue;
            }
            if let Some(rest) = a.strip_prefix("--") {
                let (long, val) = split_eq(rest);
                if long == "help" {
                    if let Some(v) = val {
                        too_many_values(v, "--help", &format!("{} <SUBCOMMAND>", ctx.top_name()));
                    }
                    show(MAIN_HELP);
                }
                let sugg = did_you_mean(long, &["help"]).pop();
                if sugg.is_some() {
                    let usage = format!("USAGE:\n    {} --help", ctx.top_name());
                    unknown_argument(&format!("--{}", long), Some("--help"), &usage);
                }
                unknown_argument(&format!("--{}", long), None, &ctx.top_usage());
            }
            if a.starts_with('-') && a.len() > 1 {
                for c in a[1..].chars() {
                    if c == 'h' {
                        show(MAIN_HELP);
                    }
                    unknown_argument(&format!("-{}", c), None, &ctx.top_usage());
                }
            }
        }
        // positional argument where a subcommand was expected
        if trailing && find_sub(a).is_some() {
            fail(format!(
                "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\n\tIf you tried to supply `{}` as a subcommand, remove the '--' before it.\n\n{}{}",
                a,
                a,
                ctx.top_usage(),
                TRY_HELP
            ));
        }
        let cands = did_you_mean(a, &all_subcommand_names());
        if !cands.is_empty() {
            let joined: Vec<String> = cands.iter().map(|c| format!("'{}'", c)).collect();
            fail(format!(
                "error: The subcommand '{}' wasn't recognized\n\n\tDid you mean {}?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\n{}{}",
                a,
                joined.join(" or "),
                ctx.top_name(),
                a,
                ctx.top_usage(),
                TRY_HELP
            ));
        }
        unknown_argument(a, None, &ctx.top_usage());
    }
    // no subcommand given
    let _ = std::io::stdout().flush();
    let mut err = std::io::stderr();
    let _ = err.write_all(MAIN_HELP.as_bytes());
    let _ = err.flush();
    std::process::exit(2);
}

fn help_subcommand(ctx: &Ctx, args: &[String]) -> ! {
    let mut cur: Option<&'static SubSpec> = None;
    for a in args {
        match cur {
            None => match find_sub(a) {
                Some(sc) => cur = Some(sc),
                None => unrecognized_subcommand(a, &ctx.top_usage()),
            },
            Some(sc) => unrecognized_subcommand(a, &ctx.sub_usage(sc)),
        }
    }
    match cur {
        None => show(MAIN_HELP),
        Some(sc) => show(&ctx.sub_help(sc)),
    }
}

struct SubState<'a> {
    ctx: &'a Ctx,
    sc: &'static SubSpec,
    present: Vec<bool>,
    vals: Vec<Option<String>>,
    pending: Option<(usize, String)>,
}

impl<'a> SubState<'a> {
    fn resolve(&mut self) -> Result<(), String> {
        if let Some((idx, v)) = self.pending.take() {
            self.present[idx] = true;
            let p = &self.sc.positionals[idx];
            if let Some(pv) = p.possible {
                if !pv.iter().any(|x| *x == v) {
                    let sugg = did_you_mean(&v, pv).pop();
                    let mut s = format!(
                        "error: {:?} isn't a valid value for '<{}>'\n\t[possible values: {}]",
                        v,
                        p.name,
                        pv.join(", ")
                    );
                    if let Some(sg) = sugg {
                        s.push_str(&format!("\n\n\tDid you mean {:?}?", sg));
                    }
                    s.push_str(TRY_HELP);
                    return Err(s);
                }
            }
            if p.path && v.is_empty() {
                return Err(format!(
                    "error: The argument '<{}>' requires a value but none was supplied{}",
                    p.name, TRY_HELP
                ));
            }
            self.vals[idx] = Some(v);
        }
        Ok(())
    }

    fn resolve_or_fail(&mut self) {
        if let Err(e) = self.resolve() {
            fail(e);
        }
    }
}

fn parse_sub(ctx: &Ctx, sc: &'static SubSpec, args: &[String]) -> Matches {
    let n = sc.positionals.len();
    let mut st = SubState { ctx, sc, present: vec![false; n], vals: vec![None; n], pending: None };
    let mut pos_counter = 0usize;
    let mut l_count = 0usize;
    let mut trailing = false;

    for a in args {
        if !trailing {
            if a == "--" {
                trailing = true;
                continue;
            }
            if let Some(rest) = a.strip_prefix("--") {
                let (long, val) = split_eq(rest);
                if long == "help" {
                    if let Some(v) = val {
                        let _ = st.resolve();
                        too_many_values(v, "--help", &ctx.sub_usage_no_title(sc));
                    }
                    st.resolve_or_fail();
                    show(&ctx.sub_help(sc));
                }
                let _ = st.resolve();
                let sugg = did_you_mean(long, &["help"]).pop();
                let usage = ctx.sub_smart_usage(sc, sugg.is_some(), l_count > 0, &st.present);
                unknown_argument(
                    &format!("--{}", long),
                    if sugg.is_some() { Some("--help") } else { None },
                    &usage,
                );
            }
            if a.starts_with('-') && a.len() > 1 {
                for c in a[1..].chars() {
                    if c == 'h' {
                        st.resolve_or_fail();
                        show(&ctx.sub_help(sc));
                    }
                    if c == 'l' && sc.has_l {
                        st.resolve_or_fail();
                        l_count += 1;
                        continue;
                    }
                    let _ = st.resolve();
                    unknown_argument(&format!("-{}", c), None, &st.ctx.sub_usage(sc));
                }
                continue;
            }
        }
        if pos_counter < n {
            st.resolve_or_fail();
            st.pending = Some((pos_counter, a.clone()));
            pos_counter += 1;
        } else {
            let _ = st.resolve();
            unknown_argument(a, None, &ctx.sub_usage(sc));
        }
    }
    st.resolve_or_fail();

    // required arguments
    let mut missing: Vec<usize> = Vec::new();
    for (i, p) in sc.positionals.iter().enumerate() {
        if p.required && !st.present[i] {
            missing.push(i);
        }
    }
    for (i, p) in sc.positionals.iter().enumerate() {
        if st.present[i] {
            if let Some(j) = p.requires {
                if !st.present[j] && !missing.contains(&j) {
                    missing.push(j);
                }
            }
        }
    }
    if !missing.is_empty() {
        missing.sort();
        let mut s = String::from("error: The following required arguments were not provided:");
        for i in &missing {
            s.push_str(&format!("\n    <{}>", sc.positionals[*i].name));
        }
        s.push_str("\n\n");
        s.push_str(&ctx.sub_usage(sc));
        s.push_str(TRY_HELP);
        fail(s);
    }
    if l_count > 1 {
        fail(format!(
            "error: The argument '-l' was provided more than once, but cannot be used multiple times\n\n{}{}",
            ctx.sub_usage(sc),
            TRY_HELP
        ));
    }

    Matches { sub: sc.name, vals: st.vals, l: l_count > 0 }
}
EOF"}

