//! A small TOML reader and a writer producing the same formatting as the
//! files written by the original tool.

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Datetime(String),
    Array(Vec<Value>),
    Table(Table),
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct Table {
    pub entries: Vec<(String, Value)>,
    /// whether the table was explicitly defined via a [header]
    pub defined: bool,
    /// inline tables can't be extended
    pub inline: bool,
}

impl Table {
    pub fn get(&self, k: &str) -> Option<&Value> {
        self.entries.iter().find(|(key, _)| key == k).map(|(_, v)| v)
    }
    fn get_mut(&mut self, k: &str) -> Option<&mut Value> {
        self.entries.iter_mut().find(|(key, _)| key == k).map(|(_, v)| v)
    }
}

struct Parser<'a> {
    s: &'a [char],
    i: usize,
}

type R<T> = Result<T, ()>;

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.s.get(self.i).copied()
    }
    fn peek_at(&self, off: usize) -> Option<char> {
        self.s.get(self.i + off).copied()
    }
    fn starts(&self, pat: &str) -> bool {
        let mut j = self.i;
        for c in pat.chars() {
            if self.s.get(j) != Some(&c) {
                return false;
            }
            j += 1;
        }
        true
    }
    fn ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' {
                self.i += 1;
            } else {
                break;
            }
        }
    }
    fn comment(&mut self) -> R<()> {
        if self.peek() == Some('#') {
            while let Some(c) = self.peek() {
                if c == '\n' {
                    break;
                }
                if c == '\r' && self.peek_at(1) == Some('\n') {
                    break;
                }
                if (c < ' ' && c != '\t') || c == '\u{7f}' {
                    return Err(());
                }
                self.i += 1;
            }
        }
        Ok(())
    }
    fn newline(&mut self) -> bool {
        if self.peek() == Some('\n') {
            self.i += 1;
            true
        } else if self.peek() == Some('\r') && self.peek_at(1) == Some('\n') {
            self.i += 2;
            true
        } else {
            false
        }
    }
    /// whitespace, comments and newlines (inside arrays)
    fn ws_nl(&mut self) -> R<()> {
        loop {
            self.ws();
            self.comment()?;
            if !self.newline() {
                break;
            }
        }
        Ok(())
    }
    fn eol(&mut self) -> R<()> {
        self.ws();
        self.comment()?;
        if self.peek().is_none() || self.newline() {
            Ok(())
        } else {
            Err(())
        }
    }

    fn key_part(&mut self) -> R<String> {
        match self.peek() {
            Some('"') => {
                if self.starts("\"\"\"") {
                    return Err(());
                }
                self.basic_string()
            }
            Some('\'') => {
                if self.starts("'''") {
                    return Err(());
                }
                self.literal_string()
            }
            _ => {
                let st = self.i;
                while let Some(c) = self.peek() {
                    if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
                        self.i += 1;
                    } else {
                        break;
                    }
                }
                if st == self.i {
                    return Err(());
                }
                Ok(self.s[st..self.i].iter().collect())
            }
        }
    }

    fn key(&mut self) -> R<Vec<String>> {
        let mut parts = Vec::new();
        loop {
            self.ws();
            parts.push(self.key_part()?);
            self.ws();
            if self.peek() == Some('.') {
                self.i += 1;
                continue;
            }
            break;
        }
        Ok(parts)
    }

    fn hex_escape(&mut self, n: usize) -> R<char> {
        let mut v: u32 = 0;
        for _ in 0..n {
            let c = self.peek().ok_or(())?;
            let d = c.to_digit(16).ok_or(())?;
            v = v * 16 + d;
            self.i += 1;
        }
        char::from_u32(v).ok_or(())
    }

    fn escape(&mut self, out: &mut String) -> R<()> {
        // at backslash
        self.i += 1;
        let c = self.peek().ok_or(())?;
        self.i += 1;
        match c {
            'b' => out.push('\u{8}'),
            't' => out.push('\t'),
            'n' => out.push('\n'),
            'f' => out.push('\u{c}'),
            'r' => out.push('\r'),
            '"' => out.push('"'),
            '\\' => out.push('\\'),
            'u' => out.push(self.hex_escape(4)?),
            'U' => out.push(self.hex_escape(8)?),
            _ => return Err(()),
        }
        Ok(())
    }

    fn basic_string(&mut self) -> R<String> {
        self.i += 1;
        let mut out = String::new();
        loop {
            let c = self.peek().ok_or(())?;
            match c {
                '"' => {
                    self.i += 1;
                    return Ok(out);
                }
                '\\' => self.escape(&mut out)?,
                '\n' | '\r' => return Err(()),
                c if (c < ' ' && c != '\t') || c == '\u{7f}' => return Err(()),
                c => {
                    out.push(c);
                    self.i += 1;
                }
            }
        }
    }

    fn literal_string(&mut self) -> R<String> {
        self.i += 1;
        let mut out = String::new();
        loop {
            let c = self.peek().ok_or(())?;
            match c {
                '\'' => {
                    self.i += 1;
                    return Ok(out);
                }
                '\n' | '\r' => return Err(()),
                c if (c < ' ' && c != '\t') || c == '\u{7f}' => return Err(()),
                c => {
                    out.push(c);
                    self.i += 1;
                }
            }
        }
    }

    fn ml_basic_string(&mut self) -> R<String> {
        self.i += 3;
        self.newline();
        let mut out = String::new();
        loop {
            if self.starts("\"\"\"") {
                // up to two additional quotes may belong to the content
                let mut extra = 0;
                while self.peek_at(3 + extra) == Some('"') && extra < 2 {
                    extra += 1;
                }
                for _ in 0..extra {
                    out.push('"');
                }
                self.i += 3 + extra;
                return Ok(out);
            }
            let c = self.peek().ok_or(())?;
            match c {
                '\\' => {
                    // line ending backslash
                    let save = self.i;
                    self.i += 1;
                    self.ws();
                    if self.peek() == Some('\n') || (self.peek() == Some('\r') && self.peek_at(1) == Some('\n')) {
                        loop {
                            self.ws();
                            if !self.newline() {
                                break;
                            }
                        }
                    } else {
                        self.i = save;
                        self.escape(&mut out)?;
                    }
                }
                '\n' => {
                    out.push('\n');
                    self.i += 1;
                }
                '\r' => {
                    if self.peek_at(1) == Some('\n') {
                        out.push('\n');
                        self.i += 2;
                    } else {
                        return Err(());
                    }
                }
                c if (c < ' ' && c != '\t') || c == '\u{7f}' => return Err(()),
                c => {
                    out.push(c);
                    self.i += 1;
                }
            }
        }
    }

    fn ml_literal_string(&mut self) -> R<String> {
        self.i += 3;
        self.newline();
        let mut out = String::new();
        loop {
            if self.starts("'''") {
                let mut extra = 0;
                while self.peek_at(3 + extra) == Some('\'') && extra < 2 {
                    extra += 1;
                }
                for _ in 0..extra {
                    out.push('\'');
                }
                self.i += 3 + extra;
                return Ok(out);
            }
            let c = self.peek().ok_or(())?;
            match c {
                '\n' => {
                    out.push('\n');
                    self.i += 1;
                }
                '\r' => {
                    if self.peek_at(1) == Some('\n') {
                        out.push('\n');
                        self.i += 2;
                    } else {
                        return Err(());
                    }
                }
                c if (c < ' ' && c != '\t') || c == '\u{7f}' => return Err(()),
                c => {
                    out.push(c);
                    self.i += 1;
                }
            }
        }
    }

    fn array(&mut self) -> R<Value> {
        self.i += 1;
        let mut items = Vec::new();
        loop {
            self.ws_nl()?;
            if self.peek() == Some(']') {
                self.i += 1;
                return Ok(Value::Array(items));
            }
            items.push(self.value()?);
            self.ws_nl()?;
            match self.peek() {
                Some(',') => {
                    self.i += 1;
                }
                Some(']') => {
                    self.i += 1;
                    return Ok(Value::Array(items));
                }
                _ => return Err(()),
            }
        }
    }

    fn inline_table(&mut self) -> R<Value> {
        self.i += 1;
        let mut t = Table { entries: Vec::new(), defined: true, inline: true };
        self.ws();
        if self.peek() == Some('}') {
            self.i += 1;
            return Ok(Value::Table(t));
        }
        loop {
            let k = self.key()?;
            if self.peek() != Some('=') {
                return Err(());
            }
            self.i += 1;
            self.ws();
            let v = self.value()?;
            insert_dotted(&mut t, &k, v)?;
            self.ws();
            match self.peek() {
                Some(',') => {
                    self.i += 1;
                }
                Some('}') => {
                    self.i += 1;
                    return Ok(Value::Table(t));
                }
                _ => return Err(()),
            }
        }
    }

    fn scalar(&mut self) -> R<Value> {
        let st = self.i;
        while let Some(c) = self.peek() {
            if c.is_ascii_alphanumeric() || c == '+' || c == '-' || c == '_' || c == '.' || c == ':' {
                self.i += 1;
            } else if c == ' ' {
                // datetime with space separator: "1979-05-27 07:32:00"
                let tok: String = self.s[st..self.i].iter().collect();
                if is_date(&tok) && self.peek_at(1).map(|d| d.is_ascii_digit()).unwrap_or(false) {
                    self.i += 1;
                } else {
                    break;
                }
            } else {
                break;
            }
        }
        let tok: String = self.s[st..self.i].iter().collect();
        if tok.is_empty() {
            return Err(());
        }
        match tok.as_str() {
            "true" => return Ok(Value::Bool(true)),
            "false" => return Ok(Value::Bool(false)),
            "inf" | "+inf" => return Ok(Value::Float(f64::INFINITY)),
            "-inf" => return Ok(Value::Float(f64::NEG_INFINITY)),
            "nan" | "+nan" | "-nan" => return Ok(Value::Float(f64::NAN)),
            _ => {}
        }
        if let Some(v) = parse_int(&tok) {
            return Ok(Value::Int(v));
        }
        if let Some(v) = parse_float(&tok) {
            return Ok(Value::Float(v));
        }
        if is_date(&tok) || tok.contains(':') {
            if tok.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
                return Ok(Value::Datetime(tok));
            }
        }
        Err(())
    }

    fn value(&mut self) -> R<Value> {
        match self.peek() {
            Some('"') => {
                if self.starts("\"\"\"") {
                    Ok(Value::Str(self.ml_basic_string()?))
                } else {
                    Ok(Value::Str(self.basic_string()?))
                }
            }
            Some('\'') => {
                if self.starts("'''") {
                    Ok(Value::Str(self.ml_literal_string()?))
                } else {
                    Ok(Value::Str(self.literal_string()?))
                }
            }
            Some('[') => self.array(),
            Some('{') => self.inline_table(),
            Some(_) => self.scalar(),
            None => Err(()),
        }
    }
}

fn is_date(tok: &str) -> bool {
    let b = tok.as_bytes();
    b.len() >= 10
        && b[..4].iter().all(|c| c.is_ascii_digit())
        && b[4] == b'-'
        && b[5..7].iter().all(|c| c.is_ascii_digit())
        && b[7] == b'-'
        && b[8..10].iter().all(|c| c.is_ascii_digit())
}

fn clean_digits(s: &str, radix: u32) -> Option<String> {
    if s.is_empty() || s.starts_with('_') || s.ends_with('_') || s.contains("__") {
        return None;
    }
    let out: String = s.chars().filter(|c| *c != '_').collect();
    if out.chars().all(|c| c.is_digit(radix)) && !out.is_empty() {
        Some(out)
    } else {
        None
    }
}

fn parse_int(tok: &str) -> Option<i64> {
    let (neg, body) = if let Some(r) = tok.strip_prefix('-') {
        (true, r)
    } else if let Some(r) = tok.strip_prefix('+') {
        (false, r)
    } else {
        (false, tok)
    };
    for (pfx, radix) in [("0x", 16), ("0o", 8), ("0b", 2)] {
        if let Some(r) = body.strip_prefix(pfx) {
            if tok.starts_with('+') || tok.starts_with('-') {
                return None;
            }
            let d = clean_digits(r, radix)?;
            return i64::from_str_radix(&d, radix).ok();
        }
    }
    let d = clean_digits(body, 10)?;
    if d.len() > 1 && d.starts_with('0') {
        return None;
    }
    let v: i64 = d.parse().ok()?;
    Some(if neg { -v } else { v })
}

fn parse_float(tok: &str) -> Option<f64> {
    let body = tok.trim_start_matches(['+', '-']);
    if body.is_empty() {
        return None;
    }
    if !(body.contains('.') || body.contains('e') || body.contains('E')) {
        return None;
    }
    let cleaned: String = tok.chars().filter(|c| *c != '_').collect();
    if !cleaned.chars().all(|c| c.is_ascii_digit() || "+-.eE".contains(c)) {
        return None;
    }
    if cleaned.starts_with('.') || cleaned.ends_with('.') || cleaned.contains(".e") || cleaned.contains(".E") {
        return None;
    }
    cleaned.parse::<f64>().ok()
}

fn insert_dotted(t: &mut Table, key: &[String], v: Value) -> R<()> {
    if key.len() == 1 {
        if t.get(&key[0]).is_some() {
            return Err(());
        }
        t.entries.push((key[0].clone(), v));
        return Ok(());
    }
    let first = &key[0];
    if t.get(first).is_none() {
        t.entries.push((first.clone(), Value::Table(Table { entries: Vec::new(), defined: false, inline: false })));
    }
    match t.get_mut(first) {
        Some(Value::Table(sub)) if !sub.inline => insert_dotted(sub, &key[1..], v),
        _ => Err(()),
    }
}

/// navigate to (creating) the table at the given header path
fn table_at<'t>(root: &'t mut Table, path: &[String], define: bool) -> R<&'t mut Table> {
    let mut cur = root;
    for (n, part) in path.iter().enumerate() {
        let last = n + 1 == path.len();
        if cur.get(part).is_none() {
            cur.entries.push((part.clone(), Value::Table(Table { entries: Vec::new(), defined: false, inline: false })));
        }
        let next = cur.get_mut(part).unwrap();
        cur = match next {
            Value::Table(t) => {
                if t.inline {
                    return Err(());
                }
                if last && define {
                    if t.defined {
                        return Err(());
                    }
                    t.defined = true;
                }
                t
            }
            Value::Array(items) => {
                if last && define {
                    return Err(());
                }
                match items.last_mut() {
                    Some(Value::Table(t)) => t,
                    _ => return Err(()),
                }
            }
            _ => return Err(()),
        };
    }
    Ok(cur)
}

pub fn parse(src: &str) -> Result<Table, ()> {
    let chars: Vec<char> = src.chars().collect();
    let mut p = Parser { s: &chars, i: 0 };
    let mut root = Table { entries: Vec::new(), defined: true, inline: false };
    let mut current: Vec<String> = Vec::new();
    // skip a BOM
    if p.peek() == Some('\u{feff}') {
        p.i += 1;
    }
    loop {
        p.ws();
        p.comment()?;
        if p.newline() {
            continue;
        }
        if p.peek().is_none() {
            break;
        }
        if p.starts("[[") {
            p.i += 2;
            let k = p.key()?;
            if !p.starts("]]") {
                return Err(());
            }
            p.i += 2;
            p.eol()?;
            // append a new table to the array
            let (parent_path, last) = k.split_at(k.len() - 1);
            let parent = table_at(&mut root, parent_path, false)?;
            match parent.get_mut(&last[0]) {
                None => parent.entries.push((
                    last[0].clone(),
                    Value::Array(vec![Value::Table(Table { entries: Vec::new(), defined: true, inline: false })]),
                )),
                Some(Value::Array(items)) => {
                    items.push(Value::Table(Table { entries: Vec::new(), defined: true, inline: false }))
                }
                _ => return Err(()),
            }
            current = k;
            continue;
        }
        if p.peek() == Some('[') {
            p.i += 1;
            let k = p.key()?;
            if p.peek() != Some(']') {
                return Err(());
            }
            p.i += 1;
            p.eol()?;
            table_at(&mut root, &k, true)?;
            current = k;
            continue;
        }
        let k = p.key()?;
        if p.peek() != Some('=') {
            return Err(());
        }
        p.i += 1;
        p.ws();
        let v = p.value()?;
        p.eol()?;
        let t = table_at(&mut root, &current, false)?;
        insert_dotted(t, &k, v)?;
    }
    Ok(root)
}

// ---------------------------------------------------------------------------
// writing

fn emit_basic(value: &str, multiline: bool) -> String {
    let mut out = String::new();
    if multiline {
        out.push_str("\"\"\"\n");
    } else {
        out.push('"');
    }
    for ch in value.chars() {
        match ch {
            '\u{8}' => out.push_str("\\b"),
            '\u{9}' => out.push_str("\\t"),
            '\u{a}' => {
                if multiline {
                    out.push('\n')
                } else {
                    out.push_str("\\n")
                }
            }
            '\u{c}' => out.push_str("\\f"),
            '\u{d}' => out.push_str("\\r"),
            '\u{22}' => out.push_str("\\\""),
            '\u{5c}' => out.push_str("\\\\"),
            c if c <= '\u{1f}' || c == '\u{7f}' => out.push_str(&format!("\\u{:04X}", c as u32)),
            c => out.push(c),
        }
    }
    if multiline {
        out.push_str("\"\"\"");
    } else {
        out.push('"');
    }
    out
}

/// Serialize a string value, preferring literal strings.
pub fn str_value(value: &str) -> String {
    #[derive(PartialEq)]
    enum Ty {
        NewlineTriple,
        OnelineTriple,
        OnelineSingle,
    }
    let mut ty = Ty::OnelineSingle;
    let mut max_found_singles = 0;
    let mut found_singles = 0;
    let mut can_be_pretty = true;
    for ch in value.chars() {
        if can_be_pretty {
            if ch == '\'' {
                found_singles += 1;
                if found_singles >= 3 {
                    can_be_pretty = false;
                }
            } else {
                if found_singles > max_found_singles {
                    max_found_singles = found_singles;
                }
