//! Locations of the configuration and data files.

use std::ffi::{CStr, OsString};
use std::os::raw::{c_char, c_int};
use std::os::unix::ffi::OsStringExt;
use std::path::PathBuf;

#[repr(C)]
struct Passwd {
    pw_name: *mut c_char,
    pw_passwd: *mut c_char,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *mut c_char,
    pw_dir: *mut c_char,
    pw_shell: *mut c_char,
}

extern "C" {
    fn getuid() -> u32;
    fn getpwuid_r(uid: u32, pwd: *mut Passwd, buf: *mut c_char, buflen: usize, result: *mut *mut Passwd) -> c_int;
}

fn home_from_passwd() -> Option<PathBuf> {
    unsafe {
        let mut buf = vec![0 as c_char; 16384];
        let mut pwd: Passwd = std::mem::zeroed();
        let mut result: *mut Passwd = std::ptr::null_mut();
        let r = getpwuid_r(getuid(), &mut pwd, buf.as_mut_ptr(), buf.len(), &mut result);
        if r != 0 || result.is_null() || pwd.pw_dir.is_null() {
            return None;
        }
        let bytes = CStr::from_ptr(pwd.pw_dir).to_bytes().to_vec();
        if bytes.is_empty() {
            return None;
        }
        Some(PathBuf::from(OsString::from_vec(bytes)))
    }
}

pub fn home_dir() -> Option<PathBuf> {
    match std::env::var_os("HOME") {
        Some(h) if !h.is_empty() => Some(PathBuf::from(h)),
        _ => home_from_passwd(),
    }
}

fn xdg(var: &str) -> Option<PathBuf> {
    std::env::var_os(var).map(PathBuf::from).filter(|p| p.is_absolute())
}

pub fn config_dir() -> Option<PathBuf> {
    xdg("XDG_CONFIG_HOME").or_else(|| home_dir().map(|h| h.join(".config")))
}

pub fn data_dir() -> Option<PathBuf> {
    xdg("XDG_DATA_HOME").or_else(|| home_dir().map(|h| h.join(".local/share")))
}
