//! Copy-and-delete based moving of files and directories.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};

pub struct MoveError {
    pub message: String,
}

impl From<io::Error> for MoveError {
    fn from(e: io::Error) -> Self {
        use io::ErrorKind::*;
        match e.kind() {
            NotFound | PermissionDenied | AlreadyExists | Interrupted | Other => {
                MoveError { message: e.to_string() }
            }
            _ => MoveError { message: "Io error".to_string() },
        }
    }
}

fn err<T>(msg: String) -> Result<T, MoveError> {
    Err(MoveError { message: msg })
}

fn get_size(path: &Path) -> Result<u64, MoveError> {
    let mut result = 0;
    if path.is_dir() {
        for entry in fs::read_dir(path)? {
            let p = entry?.path();
            if p.is_file() {
                result += p.metadata()?.len();
            } else {
                result += get_size(&p)?;
            }
        }
    } else {
        result = path.metadata()?.len();
    }
    Ok(result)
}

fn dir_content(path: &Path, dirs: &mut Vec<PathBuf>, files: &mut Vec<PathBuf>) -> Result<(), MoveError> {
    if path.to_str().is_none() {
        return err("Invalid path".to_string());
    }
    if path.is_dir() {
        dirs.push(path.to_path_buf());
        for entry in fs::read_dir(path)? {
            let p = entry?.path();
            dir_content(&p, dirs, files)?;
        }
    } else {
        path.metadata()?;
        files.push(path.to_path_buf());
    }
    Ok(())
}

