//! Implementation of the commands.

use crate::cli::Matches;
use crate::fatal::{panic_at, unwrap_err, NONE_UNWRAP};
use crate::fsx;
use crate::state::{Config, FileData, VaultData, Vaults};
use std::fs;
use std::io::{ErrorKind, Write};
use std::path::{Path, PathBuf};
use std::process::Command;

const BLUE: &str = "\x1b[0;34m";
const RESET: &str = "\x1b[0m";

fn hl(s: &str) -> String {
    format!("{}{}{}", BLUE, s, RESET)
}

/// error raised by a command, printed to stdout
struct Fail(String);

type Res = Result<(), Fail>;

fn fail<T>(msg: impl Into<String>) -> Result<T, Fail> {
    Err(Fail(msg.into()))
}

fn undefined(e: std::io::Error) -> Fail {
    Fail(format!("undefined error: {}", e))
}

fn moved_err(e: fsx::MoveError) -> Fail {
    Fail(e.message.to_lowercase())
}

fn invalid_name(name: &str) -> bool {
    name.chars().any(|c| matches!(c, '"' | '%' | '*' | '/' | ':' | '<' | '>' | '?' | '\\' | '|'))
}

#[derive(Clone, Copy, PartialEq)]
enum Item {
    Vault,
    Note,
    Folder,
}

impl Item {
    fn parse(s: &str) -> Item {
        match s {
            "vault" | "vl" => Item::Vault,
            "note" | "nt" => Item::Note,
            _ => Item::Folder,
        }
    }
    fn word(self) -> &'static str {
        match self {
            Item::Vault => "vault",
            Item::Note => "note",
            Item::Folder => "folder",
        }
    }
}

pub struct App {
    config: Config,
    vaults: Vaults,
    data: Option<VaultData>,
}

/// Location information of the current vault.
struct Here {
    vault_path: PathBuf,
    folder_path: PathBuf,
}

impl App {
    pub fn load() -> App {
        let config = Config::load(&Config::path());
        let vaults = Vaults::load(&Vaults::path());
        let data = match &vaults.current {
            Some(cur) => {
                let loc = match vaults.vaults.get(cur) {
                    Some(l) => l.clone(),
                    None => panic_at("src/state/vaults/mod.rs:32:91", NONE_UNWRAP),
                };
                Some(VaultData::load(&VaultData::data_path(&loc.join(cur))))
            }
            None => None,
        };
        App { config, vaults, data }
    }

    pub fn run(&mut self, m: &Matches) {
        let r = match m.sub {
            "vault" => match (m.get(0), m.get(1)) {
                (Some(n), Some(l)) => self.create_vault(n, l),
                _ => {
                    self.list_vaults(m.l);
                    Ok(())
                }
            },
            "note" => self.create_note(m.get(0).unwrap_or("")),
            "folder" => self.create_folder(m.get(0).unwrap_or("")),
            "enter" => self.enter(m.get(0).unwrap_or("")),
            "open" => self.open(m.get(0).unwrap_or("")),
            "opdir" => self.opdir(),
            "chdir" => self.chdir(m.get(0).unwrap_or("")),
            "list" => self.list(m.get(0).map(Item::parse)),
            "remove" => self.remove(Item::parse(m.get(0).unwrap_or("")), m.get(1).unwrap_or("")),
            "rename" => self.rename(
                Item::parse(m.get(0).unwrap_or("")),
                m.get(1).unwrap_or(""),
                m.get(2).unwrap_or(""),
            ),
            "move" => self.move_item(
                Item::parse(m.get(0).unwrap_or("")),
                m.get(1).unwrap_or(""),
                m.get(2).unwrap_or(""),
            ),
            "vmove" => self.vmove(
                Item::parse(m.get(0).unwrap_or("")),
                m.get(1).unwrap_or(""),
                m.get(2).unwrap_or(""),
            ),
            "config" => self.config_cmd(m.get(0), m.get(1)),
            _ => Ok(()),
        };
        if let Err(Fail(msg)) = r {
            println!("\x1b[0;31merror\x1b[0m: {}", msg);
        }
        let _ = std::io::stdout().flush();
    }

    // -- helpers ---------------------------------------------------------

    fn data(&self) -> Result<&VaultData, Fail> {
        match &self.data {
            Some(d) => Ok(d),
            None => fail("not inside a vault"),
        }
