    fn create_vault(&mut self, name: &str, location: &str) -> Res {
        if self.vaults.vaults.contains_key(name) {
            return fail(format!("vault {} already exists", name));
        }
        let location = PathBuf::from(location);
        if !location.is_absolute() {
            return fail("specified path isn't absolute");
        }
        let location = match fs::canonicalize(&location) {
            Ok(l) => l,
            Err(_) => return fail("couldn't find the path specified"),
        };
        if invalid_name(name) {
            return fail("invalid name");
        }
        let path = location.join(name);
        if path.exists() {
            return fail(format!("a folder named {} already exists in this location", name));
        }
        fs::create_dir(&path).map_err(undefined)?;
        let data = VaultData {
            name: Some(name.to_string()),
            location: Some(location.clone()),
            folder: PathBuf::new(),
            history: Vec::new(),
        };
        data.store(&VaultData::data_path(&path));
        self.vaults.vaults.insert(name.to_string(), location);
        self.vaults.save();
        println!("vault {} created", hl(name));
        Ok(())
    }

    fn enter(&mut self, name: &str) -> Res {
        if !self.vaults.vaults.contains_key(name) {
            return fail(format!("vault {} doesn't exist", name));
        }
        if self.vaults.current.as_deref() == Some(name) {
            return fail(format!("already in vault {}", name));
        }
        self.vaults.current = Some(name.to_string());
        self.vaults.save();
        println!("entered {}", hl(name));
        Ok(())
    }

    // -- items -----------------------------------------------------------

    fn create_note(&mut self, name: &str) -> Res {
        let here = self.here()?;
        if invalid_name(name) {
            return fail("invalid name");
        }
        let path = here.folder_path.join(name).with_extension("md");
        if path.exists() {
            return fail(format!("a note named {} already exists in this location", name));
        }
        fs::File::create(&path).map_err(undefined)?;
        println!("note {} created", hl(name));
        Ok(())
    }

    fn create_folder(&mut self, name: &str) -> Res {
        let here = self.here()?;
        if invalid_name(name) {
            return fail("invalid name");
        }
        let path = here.folder_path.join(name);
        if path.exists() {
            return fail(format!("a folder named {} already exists in this location", name));
        }
        fs::create_dir(&path).map_err(undefined)?;
        println!("folder {} created", hl(name));
        Ok(())
    }

    fn open(&mut self, name: &str) -> Res {
        let here = self.here()?;
        if invalid_name(name) {
            return fail("invalid name");
        }
        let path = here.folder_path.join(name).with_extension("md");
        if !path.exists() {
            return fail(format!("note {} not found", name));
        }
        self.run_editor(&path)
    }

    fn opdir(&mut self) -> Res {
        let here = self.here()?;
        match Command::new("xdg-open").arg(&here.folder_path).spawn() {
            Ok(_) => Ok(()),
            Err(e) => Err(undefined(e)),
        }
    }

    fn chdir(&mut self, target: &str) -> Res {
