            return fail(format!("a {} named {} already exists in this location", kind.word(), name));
        }
        fsx::move_item(&src, &dest).map_err(moved_err)?;
        println!("{} {} moved", kind.word(), hl(name));
        Ok(())
    }

    fn vmove(&mut self, kind: Item, name: &str, vault: &str) -> Res {
        let target_loc = match self.vaults.vaults.get(vault) {
            Some(l) => l.clone(),
            None => return fail(format!("vault {} doesn't exist", name)),
        };
        let here = self.here()?;
        if self.vaults.current.as_deref() == Some(vault) {
            print!("{} {} already exists in vault {}", kind.word(), name, vault);
            return fail("new location is same as old location");
        }
        if invalid_name(name) {
            return fail("invalid name");
        }
        let target_dir = target_loc.join(vault);
        let (src, dst) = if kind == Item::Note {
            (here.folder_path.join(name).with_extension("md"), target_dir.join(name).with_extension("md"))
        } else {
            (here.folder_path.join(name), target_dir.join(name))
        };
        if dst.exists() {
            return fail(format!("a {} named {} already exists in this location", kind.word(), name));
        }
        fsx::move_item(&src, &target_dir).map_err(moved_err)?;
        println!("{} {} moved to vault {}", kind.word(), hl(name), hl(vault));
        Ok(())
    }

    // -- config ----------------------------------------------------------

    fn config_cmd(&mut self, kind: Option<&str>, value: Option<&str>) -> Res {
        match kind {
            None => self.run_editor(&Config::path()),
            Some(k) => {
                match value {
                    None => {
                        let v = if k == "editor" { self.config.editor.clone() } else { self.config.conflict.to_string() };
                        println!("{}: {}", k, hl(&v));
                    }
                    Some(v) => {
                        if k == "editor" {
                            self.config.editor = v.to_string();
                        } else {
                            match v.parse::<bool>() {
                                Ok(b) => self.config.conflict = b,
                                Err(e) => unwrap_err("src/state/config.rs:74:42", e),
                            }
                        }
                        self.config.store(&Config::path());
                        println!("set {} to {}", hl(k), hl(v));
                    }
                }
                Ok(())
            }
        }
    }
}

fn stem(p: &Path) -> String {
    p.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default()
}

fn print_tree(path: &Path, prefix: &str) {
    let rd = match fs::read_dir(path) {
        Ok(r) => r,
        Err(e) => unwrap_err("src/utils.rs:189:34", e),
    };
    let mut entries = Vec::new();
    for e in rd {
        match e {
            Ok(e) => entries.push(e),
            Err(e) => unwrap_err("src/utils.rs:190:43", e),
        }
    }
    let n = entries.len();
    for (i, e) in entries.iter().enumerate() {
        let p = e.path();
        if p.file_name().map(|f| f == ".jot").unwrap_or(false) {
            continue;
        }
        let last = i + 1 == n;
        let conn = if last { "└── " } else { "├── " };
        if p.is_dir() {
            println!("{}{}{}", prefix, conn, stem(&p));
            let next = format!("{}{}", prefix, if last { "    " } else { "│   " });
            print_tree(&p, &next);
        } else {
            let is_note = match p.extension() {
                None => true,
                Some(ext) => ext == "md",
            };
            if is_note {
                println!("{}{}{}", prefix, conn, hl(&stem(&p)));
            }
        }
    }
}
