cd /workspace; cat > src/cmds.rs <<'EOF'
//! Implementation of the commands.

use crate::cli::Matches;
use crate::fatal::{panic_at, unwrap_err, NONE_UNWRAP};
use crate::fsx;
use crate::state::{Config, FileData, VaultData, Vaults};
use std::fs;
use std::io::{ErrorKind, Write};
use std::path::{Path, PathBuf};
use std::process::Command;

const BLUE: &str = "\x1b[0;34m";
const RESET: &str = "\x1b[0m";

fn hl(s: &str) -> String {
    format!("{}{}{}", BLUE, s, RESET)
}

/// error raised by a command, printed to stdout
struct Fail(String);

type Res = Result<(), Fail>;

fn fail<T>(msg: impl Into<String>) -> Result<T, Fail> {
    Err(Fail(msg.into()))
}

fn undefined(e: std::io::Error) -> Fail {
    Fail(format!("undefined error: {}", e))
}

fn moved_err(e: fsx::MoveError) -> Fail {
    Fail(e.message.to_lowercase())
}

fn invalid_name(name: &str) -> bool {
    name.chars().any(|c| matches!(c, '"' | '%' | '*' | '/' | ':' | '<' | '>' | '?' | '\\' | '|'))
}

#[derive(Clone, Copy, PartialEq)]
enum Item {
    Vault,
    Note,
    Folder,
}

impl Item {
    fn parse(s: &str) -> Item {
        match s {
            "vault" | "vl" => Item::Vault,
            "note" | "nt" => Item::Note,
            _ => Item::Folder,
        }
    }
    fn word(self) -> &'static str {
        match self {
            Item::Vault => "vault",
            Item::Note => "note",
            Item::Folder => "folder",
        }
    }
}

pub struct App {
    config: Config,
    vaults: Vaults,
    data: Option<VaultData>,
}

/// Location information of the current vault.
struct Here {
    vault_path: PathBuf,
    folder_path: PathBuf,
}

impl App {
    pub fn load() -> App {
        let config = Config::load(&Config::path());
        let vaults = Vaults::load(&Vaults::path());
        let data = match &vaults.current {
            Some(cur) => {
                let loc = match vaults.vaults.get(cur) {
                    Some(l) => l.clone(),
                    None => panic_at("src/state/vaults/mod.rs:32:91", NONE_UNWRAP),
                };
                Some(VaultData::load(&VaultData::data_path(&loc.join(cur))))
            }
            None => None,
        };
        App { config, vaults, data }
    }

    pub fn run(&mut self, m: &Matches) {
        let r = match m.sub {
            "vault" => match (m.get(0), m.get(1)) {
                (Some(n), Some(l)) => self.create_vault(n, l),
                _ => {
                    self.list_vaults(m.l);
                    Ok(())
                }
            },
            "note" => self.create_note(m.get(0).unwrap_or("")),
            "folder" => self.create_folder(m.get(0).unwrap_or("")),
            "enter" => self.enter(m.get(0).unwrap_or("")),
            "open" => self.open(m.get(0).unwrap_or("")),
            "opdir" => self.opdir(),
            "chdir" => self.chdir(m.get(0).unwrap_or("")),
            "list" => self.list(m.get(0).map(Item::parse)),
            "remove" => self.remove(Item::parse(m.get(0).unwrap_or("")), m.get(1).unwrap_or("")),
            "rename" => self.rename(
                Item::parse(m.get(0).unwrap_or("")),
                m.get(1).unwrap_or(""),
                m.get(2).unwrap_or(""),
            ),
            "move" => self.move_item(
                Item::parse(m.get(0).unwrap_or("")),
                m.get(1).unwrap_or(""),
                m.get(2).unwrap_or(""),
            ),
            "vmove" => self.vmove(
                Item::parse(m.get(0).unwrap_or("")),
                m.get(1).unwrap_or(""),
                m.get(2).unwrap_or(""),
            ),
            "config" => self.config_cmd(m.get(0), m.get(1)),
            _ => Ok(()),
        };
        if let Err(Fail(msg)) = r {
            println!("\x1b[0;31merror\x1b[0m: {}", msg);
        }
        let _ = std::io::stdout().flush();
    }

    // -- helpers ---------------------------------------------------------

    fn data(&self) -> Result<&VaultData, Fail> {
        match &self.data {
            Some(d) => Ok(d),
            None => fail("not inside a vault"),
        }
    }

    fn data_name(d: &VaultData) -> String {
        match &d.name {
            Some(n) => n.clone(),
            None => panic_at("src/state/vaults/vault.rs:44:28", NONE_UNWRAP),
        }
    }

    fn data_location(d: &VaultData) -> PathBuf {
        match &d.location {
            Some(l) => l.clone(),
            None => panic_at("src/state/vaults/vault.rs:55:32", NONE_UNWRAP),
        }
    }

    fn here(&self) -> Result<Here, Fail> {
        let d = self.data()?;
        let name = Self::data_name(d);
        let location = Self::data_location(d);
        let vault_path = location.join(name);
        let folder_path = vault_path.join(&d.folder);
        Ok(Here { vault_path, folder_path })
    }

    fn run_editor(&self, path: &Path) -> Res {
        match Command::new(&self.config.editor).arg(path).status() {
            Ok(_) => Ok(()),
            Err(e) if e.kind() == ErrorKind::NotFound => fail("editor not found"),
            Err(e) => Err(undefined(e)),
        }
    }

    // -- vaults ----------------------------------------------------------

    fn list_vaults(&self, show_location: bool) {
        let mut out = String::new();
        for (name, loc) in &self.vaults.vaults {
            if self.vaults.current.as_deref() == Some(name.as_str()) {
                out.push_str(&format!("\u{1f449} {}", hl(name)));
            } else {
                out.push_str(&format!("   {}", name));
            }
            if show_location {
                out.push_str(&format!(" \t {}", loc.display()));
            }
            out.push('\n');
            print!("{}", out);
            out.clear();
        }
    }

    fn create_vault(&mut self, name: &str, location: &str) -> Res {
        if self.vaults.vaults.contains_key(name) {
            return fail(format!("vault {} already exists", name));
        }
        let location = PathBuf::from(location);
        if !location.is_absolute() {
            return fail("specified path isn't absolute");
        }
        let location = match fs::canonicalize(&location) {
            Ok(l) => l,
            Err(_) => return fail("couldn't find the path specified"),
        };
        if invalid_name(name) {
            return fail("invalid name");
        }
        let path = location.join(name);
        if path.exists() {
            return fail(format!("a folder named {} already exists in this location", name));
        }
        fs::create_dir(&path).map_err(undefined)?;
        let data = VaultData {
            name: Some(name.to_string()),
            location: Some(location.clone()),
            folder: PathBuf::new(),
            history: Vec::new(),
        };
        data.store(&VaultData::data_path(&path));
        self.vaults.vaults.insert(name.to_string(), location);
        self.vaults.save();
        println!("vault {} created", hl(name));
        Ok(())
    }

    fn enter(&mut self, name: &str) -> Res {
        if !self.vaults.vaults.contains_key(name) {
            return fail(format!("vault {} doesn't exist", name));
        }
        if self.vaults.current.as_deref() == Some(name) {
            return fail(format!("already in vault {}", name));
        }
        self.vaults.current = Some(name.to_string());
        self.vaults.save();
        println!("entered {}", hl(name));
        Ok(())
    }

    // -- items -----------------------------------------------------------

    fn create_note(&mut self, name: &str) -> Res {
        let here = self.here()?;
        if invalid_name(name) {
            return fail("invalid name");
        }
        let path = here.folder_path.join(name).with_extension("md");
        if path.exists() {
            return fail(format!("a note named {} already exists in this location", name));
        }
        fs::File::create(&path).map_err(undefined)?;
        println!("note {} created", hl(name));
        Ok(())
    }

    fn create_folder(&mut self, name: &str) -> Res {
        let here = self.here()?;
        if invalid_name(name) {
            return fail("invalid name");
        }
        let path = here.folder_path.join(name);
        if path.exists() {
            return fail(format!("a folder named {} already exists in this location", name));
        }
        fs::create_dir(&path).map_err(undefined)?;
        println!("folder {} created", hl(name));
        Ok(())
    }

    fn open(&mut self, name: &str) -> Res {
        let here = self.here()?;
        if invalid_name(name) {
            return fail("invalid name");
        }
        let path = here.folder_path.join(name).with_extension("md");
        if !path.exists() {
            return fail(format!("note {} not found", name));
        }
        self.run_editor(&path)
    }

    fn opdir(&mut self) -> Res {
        let here = self.here()?;
        match Command::new("xdg-open").arg(&here.folder_path).spawn() {
            Ok(_) => Ok(()),
            Err(e) => Err(undefined(e)),
        }
    }

    fn chdir(&mut self, target: &str) -> Res {
        let here = self.here()?;
        let dest = match fs::canonicalize(here.folder_path.join(target)) {
            Ok(d) => d,
            Err(_) => return fail("couldn't find the path specified"),
        };
        if !dest.starts_with(&here.vault_path) {
            return fail("path crosses the bounds of vault");
        }
        if dest == here.folder_path {
            return fail("new location is same as old location");
        }
        let rel = dest.strip_prefix(&here.vault_path).map(|p| p.to_path_buf()).unwrap_or_default();
        if let Some(d) = self.data.as_mut() {
            d.folder = rel;
            d.save();
        }
        println!("folder changed");
        Ok(())
    }

    fn list(&mut self, kind: Option<Item>) -> Res {
        let d = self.data()?;
        let name = Self::data_name(d);
        if d.folder.as_os_str().is_empty() {
            println!("{}", name);
        } else {
            println!("{} > {}", name, d.folder.display());
        }
        let location = Self::data_location(d);
        let folder_path = location.join(&name).join(&d.folder);
        match kind {
            None => print_tree(&folder_path, ""),
            Some(k) => {
                let entries = match fs::read_dir(&folder_path) {
                    Ok(e) => e,
                    Err(e) => unwrap_err("src/utils.rs:149:34", e),
                };
                let mut items: Vec<String> = Vec::new();
                for entry in entries {
                    let entry = match entry {
                        Ok(e) => e,
                        Err(e) => unwrap_err("src/utils.rs:150:43", e),
                    };
                    let p = entry.path();
                    let keep = if k == Item::Note {
                        p.is_file()
                            && match p.extension() {
                                Some(ext) => ext == "md",
                                None => panic_at("src/utils.rs:160:57", NONE_UNWRAP),
                            }
                    } else {
                        p.is_dir()
                    };
                    if keep {
                        items.push(stem(&p));
                    }
                }
                let n = items.len();
                let mut out = String::new();
                for (i, it) in items.iter().enumerate() {
                    let conn = if i + 1 == n { "└── " } else { "├── " };
                    if k == Item::Note {
                        out.push_str(&format!("{}{}\n", conn, hl(it)));
                    } else {
                        out.push_str(&format!("{}{}\n", conn, it));
                    }
                }
                print!("{}", out);
            }
        }
        Ok(())
    }

    fn remove(&mut self, kind: Item, name: &str) -> Res {
        match kind {
            Item::Vault => {
                let loc = match self.vaults.vaults.get(name) {
                    Some(l) => l.clone(),
                    None => return fail(format!("vault {} doesn't exist", name)),
                };
                let path = loc.join(name);
                if !path.exists() {
                    return fail(format!("folder {} not found", name));
                }
                fs::remove_dir_all(&path).map_err(undefined)?;
                self.vaults.vaults.remove(name);
                if self.vaults.current.as_deref() == Some(name) {
                    self.vaults.current = None;
                }
                self.vaults.save();
                println!("vault {} removed", hl(name));
                Ok(())
            }
            Item::Note => {
                let here = self.here()?;
                if invalid_name(name) {
                    return fail("invalid name");
                }
                let path = here.folder_path.join(name).with_extension("md");
                if !path.exists() {
                    return fail(format!("note {} not found", name));
                }
                fs::remove_file(&path).map_err(undefined)?;
                println!("note {} removed", hl(name));
                Ok(())
            }
            Item::Folder => {
                let here = self.here()?;
                if invalid_name(name) {
                    return fail("invalid name");
                }
                let path = here.folder_path.join(name);
                if !path.exists() {
                    return fail(format!("folder {} not found", name));
                }
                fs::remove_dir_all(&path).map_err(undefined)?;
                println!("folder {} removed", hl(name));
                Ok(())
            }
        }
    }

    fn rename(&mut self, kind: Item, old: &str, new: &str) -> Res {
        if kind == Item::Vault {
            if self.vaults.vaults.contains_key(new) {
                return fail(format!("vault {} already exists", new));
            }
            let loc = match self.vaults.vaults.get(old) {
                Some(l) => l.clone(),
                None => return fail(format!("vault {} doesn't exist", old)),
            };
            if invalid_name(new) {
                return fail("invalid name");
            }
            let new_path = loc.join(new);
            fs::rename(loc.join(old), &new_path).map_err(undefined)?;
            let mut data = VaultData::load(&VaultData::data_path(&new_path));
            data.name = Some(new.to_string());
            data.save();
            self.vaults.vaults.remove(old);
            self.vaults.vaults.insert(new.to_string(), loc);
            if self.vaults.current.as_deref() == Some(old) {
                self.vaults.current = Some(new.to_string());
            }
            self.vaults.save();
            println!("vault {} renamed to {}", hl(old), hl(new));
            return Ok(());
        }
        let here = self.here()?;
        if old == new {
            return fail("new name is same as old name");
        }
        if invalid_name(old) || invalid_name(new) {
            return fail("invalid name");
        }
        let (old_path, new_path) = if kind == Item::Note {
            (
                here.folder_path.join(old).with_extension("md"),
                here.folder_path.join(new).with_extension("md"),
            )
        } else {
            (here.folder_path.join(old), here.folder_path.join(new))
        };
        if !old_path.exists() {
            return fail(format!("{} {} not found", kind.word(), old));
        }
        fs::rename(&old_path, &new_path).map_err(undefined)?;
        println!("{} {} renamed to {}", kind.word(), hl(old), hl(new));
        Ok(())
    }

    fn move_item(&mut self, kind: Item, name: &str, target: &str) -> Res {
        if kind == Item::Vault {
            let old_loc = match self.vaults.vaults.get(name) {
                Some(l) => l.clone(),
                None => return fail(format!("vault {} doesn't exist", name)),
            };
            let new_loc = PathBuf::from(target);
            if new_loc == old_loc {
                return fail("new location is same as old location");
            }
            if !new_loc.is_absolute() {
                return fail("specified path isn't absolute");
            }
            if new_loc.join(name).exists() {
                return fail(format!("a folder named {} already exists in this location", name));
            }
            fsx::move_item(&old_loc.join(name), &new_loc).map_err(moved_err)?;
            let canonical = match fs::canonicalize(&new_loc) {
                Ok(c) => c,
                Err(_) => return fail("couldn't find the path specified"),
            };
            let mut data = VaultData::load(&VaultData::data_path(&canonical.join(name)));
            data.location = Some(canonical.clone());
            data.save();
            self.vaults.vaults.insert(name.to_string(), canonical);
            self.vaults.save();
            println!("vault {} moved", hl(name));
            return Ok(());
        }
        let here = self.here()?;
        let dest = match fs::canonicalize(here.folder_path.join(target)) {
            Ok(d) => d,
            Err(_) => return fail("couldn't find the path specified"),
        };
        if !dest.starts_with(&here.vault_path) {
            return fail("path crosses the bounds of vault");
        }
        if dest == here.folder_path {
            return fail("new location is same as old location");
        }
        if invalid_name(name) {
            return fail("invalid name");
        }
        let (src, dst) = if kind == Item::Note {
            (here.folder_path.join(name).with_extension("md"), dest.join(name).with_extension("md"))
        } else {
            (here.folder_path.join(name), dest.join(name))
        };
        if dst.exists() {
            return fail(format!("a {} named {} already exists in this location", kind.word(), name));
        }
        fsx::move_item(&src, &dest).map_err(moved_err)?;
        println!("{} {} moved", kind.word(), hl(name));
        Ok(())
    }

    fn vmove(&mut self, kind: Item, name: &str, vault: &str) -> Res {
        let target_loc = match self.vaults.vaults.get(vault) {
            Some(l) => l.clone(),
            None => return fail(format!("vault {} doesn't exist", name)),
        };
        let here = self.here()?;
        if self.vaults.current.as_deref() == Some(vault) {
            print!("{} {} already exists in vault {}", kind.word(), name, vault);
            return fail("new location is same as old location");
        }
        if invalid_name(name) {
            return fail("invalid name");
        }
        let target_dir = target_loc.join(vault);
        let (src, dst) = if kind == Item::Note {
            (here.folder_path.join(name).with_extension("md"), target_dir.join(name).with_extension("md"))
        } else {
            (here.folder_path.join(name), target_dir.join(name))
        };
        if dst.exists() {
            return fail(format!("a {} named {} already exists in this location", kind.word(), name));
        }
        fsx::move_item(&src, &target_dir).map_err(moved_err)?;
        println!("{} {} moved to vault {}", kind.word(), hl(name), hl(vault));
        Ok(())
    }

    // -- config ----------------------------------------------------------

    fn config_cmd(&mut self, kind: Option<&str>, value: Option<&str>) -> Res {
        match kind {
            None => self.run_editor(&Config::path()),
            Some(k) => {
                match value {
                    None => {
                        let v = if k == "editor" { self.config.editor.clone() } else { self.config.conflict.to_string() };
                        println!("{}: {}", k, hl(&v));
                    }
                    Some(v) => {
                        if k == "editor" {
                            self.config.editor = v.to_string();
                        } else {
                            match v.parse::<bool>() {
                                Ok(b) => self.config.conflict = b,
                                Err(e) => unwrap_err("src/state/config.rs:74:42", e),
                            }
                        }
                        self.config.store(&Config::path());
                        println!("set {} to {}", hl(k), hl(v));
                    }
                }
                Ok(())
            }
        }
    }
}

fn stem(p: &Path) -> String {
    p.file_stem().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default()
}

fn print_tree(path: &Path, prefix: &str) {
    let rd = match fs::read_dir(path) {
        Ok(r) => r,
        Err(e) => unwrap_err("src/utils.rs:189:34", e),
    };
    let mut entries = Vec::new();
    for e in rd {
        match e {
            Ok(e) => entries.push(e),
            Err(e) => unwrap_err("src/utils.rs:190:43", e),
        }
    }
    let n = entries.len();
    for (i, e) in entries.iter().enumerate() {
        let p = e.path();
        if p.file_name().map(|f| f == ".jot").unwrap_or(false) {
            continue;
        }
        let last = i + 1 == n;
        let conn = if last { "└── " } else { "├── " };
        if p.is_dir() {
            println!("{}{}{}", prefix, conn, stem(&p));
            let next = format!("{}{}", prefix, if last { "    " } else { "│   " });
            print_tree(&p, &next);
        } else {
            let is_note = match p.extension() {
                None => true,
                Some(ext) => ext == "md",
            };
            if is_note {
                println!("{}{}{}", prefix, conn, hl(&stem(&p)));
            }
        }
    }
}
